const S = '/tmp/claude-0/-home-user-Vel-n/a6963cc3-5559-53b7-8eeb-5fd2cdb37dae/scratchpad'
const SB = S + '/sqlb'
const R = '/home/user/Vel-n'
const H = R + '/.claude/handoff'

const CTX = [
  'CONTEXT. Repo ' + R + ' (MotoGo24 motorcycle rental: Flutter customer app in two trees, Velin admin in React, Supabase backend, PHP website), branch claude/moto-go-mobile-conversion-gqg5qo, draft PR #2214. The owner merges without reading. Merge into main = immediate LIVE deployment: .github/workflows/deploy-sql.yml applies every file of supabase/migrations/*.sql that is not yet recorded in public._git_migrations, in LC_ALL=C byte order of the file name, each one with: psql -v ON_ERROR_STOP=1 --single-transaction -f <file> (as the database owner). A failing file aborts the run and BLOCKS every later file until it is fixed; edge functions (supabase/functions) and Velin deploy in parallel from the same merge. Therefore every migration must be final, valid on the live database of TODAY, idempotent (a second run changes nothing and raises no error), free of BEGIN/COMMIT, and must not be able to fail because of live DATA (duplicates under a new unique index, rows violating a new constraint, missing rows, unexpected NULLs or JSON shapes, long table rewrites or locks on big tables, statement timeouts).',
  'LIVE STATE. The only truth about the live schema is the git branch origin/supabase-live-snapshot (commit e5d5b0f7, 2026-11-12 11:01 UTC; files supabase/_snapshot/roles.sql, schema_system.sql, schema_public.sql, triggers.sql; read with: git -C ' + R + ' show origin/supabase-live-snapshot:supabase/_snapshot/<file>). It is schema only, no data. Everything up to supabase/migrations/20261023f_faq_gear_rental.sql is live. The drafts were written between 2026-10-15 and 2026-11-07 against OLDER live states; since then main received gear-only rental (20261022*, 20261023*), unified refunds (20261023e_*), a storno hotfix, kiosk work and more. A draft that does CREATE OR REPLACE on a function / trigger function / view, or re-creates a trigger or policy, starting from an OLDER body would silently undo those live changes. Preventing that is the main point of this work: every replaced object must be the live body of today plus exactly the intended change.',
  'READING LIVE DATA. Public rows may be read (HTTP GET only) through the REST API https://vnwnqteskbykeucanlhk.supabase.co/rest/v1/<table>?select=... with the public anon key that the website already ships (see motogo-web-php/config.php; send it as the apikey header and as Authorization: Bearer). Strictly read-only: never POST/PATCH/PUT/DELETE, never call /rpc/ endpoints, never use any other key, never write the key into a report or a file you create (read it from config.php at run time). A table without anon read access returns [] or an error - then say "not readable" and rely on guards inside the SQL.',
  'DOCS. Project rules are in CLAUDE.md (already in your context). The backend docs SUPABASE_BACKEND_STATE_1..6.md are huge (2 MB) - grep them for the objects you touch, never read them whole.',
  'RULES. (1) No git write commands at all (no add, commit, push, checkout, switch, stash, reset, restore, merge, rebase, worktree, clean); read-only git (show, diff, log, grep, ls-tree) is fine. The orchestrator commits. (2) Never modify or delete existing files under supabase/migrations - they are applied live. (3) Do not change app, Velin, web or edge-function code; if code and SQL disagree, report it precisely. (4) PostgreSQL 16 binaries are in /usr/lib/postgresql/16/bin; clusters only under /var/tmp; run them as the postgres OS user (runuser -u postgres -- ...); the postgres user cannot read the scratchpad, so feed SQL through stdin. (5) psql may only ever connect to the local test cluster (unix socket). (6) Your work directory: ' + SB + ' (create sub-directories as told). (7) Several agents work in parallel on other groups: use only your own database and only your own file names; do not stop or re-initialise the shared cluster. (8) Reports in plain English with full sentences; comments inside migration files in Czech (repo convention). (9) State only what you verified; say plainly what you could not verify.',
  'FILE NAMING (final, deploy evidence is by file name): supabase/migrations/20261112<g><nn>_<slug>.sql, <g> = group letter, <nn> = two-digit sequence from 01. Groups: a = payments, b = ride recording, c = reviews and messages, d = loyalty rank colours, t = owner texts, u = QA text fixes. Byte order gives a < b < c < d < t < u, all after 20261023f_: functional migrations run before text/data migrations, so a failing text file can never block a functional one.',
  'MIGRATION FILE FORM: Czech header comment (what it does, why, the owner request with its date where there is one, idempotency note, what it deliberately does not touch); no wording like "NAVRH", "ke schvaleni", "neaplikovano"; no BEGIN/COMMIT; nothing that cannot run inside one transaction (no CREATE INDEX CONCURRENTLY, no VACUUM, no ALTER TYPE ... ADD VALUE used in the same file); SECURITY DEFINER functions carry SET search_path; GRANT/REVOKE follow what live does for sibling functions; idempotency through CREATE OR REPLACE, IF NOT EXISTS, DROP ... IF EXISTS and guarded DO blocks. Repo rule: at most about 5000 tokens per file where technically possible without limiting function - keep one atomic all-or-nothing change in one file even when it is larger, split only independent units (and then keep the dependency order in the sequence numbers).',
].join('\n\n')

const HARNESS_DOC = SB + '/pg/README.md'

phase('Harness')
const harness = await agent(CTX + '\n\nTASK harness. Build a reusable PG16 test rig in ' + SB + '/pg and document it in ' + HARNESS_DOC + ' (other agents will read only that file). An older rig existed (see ' + H + '/rides/setup.sh and section 1 of ' + H + '/rides/understand_server.md for how it worked) but its stubs.sql, timeshim.sql and fixtures are lost - rebuild what is needed.\n'
  + 'Requirements:\n'
  + '1. One cluster /var/tmp/pg-sqlb (port 5498, unix socket only, timezone UTC, fsync off), owned by the postgres OS user.\n'
  + '2. A template database live_tpl = the live schema of today: stubs first (roles as in roles.sql and as Supabase has them: anon, authenticated, service_role, supabase_admin, authenticator ...; schemas auth/extensions/storage/vault/net/cron/supabase_functions as far as the public schema needs them; auth.users, auth.uid(), auth.role(), auth.jwt() as live; extensions that exist locally (uuid-ossp, pgcrypto, pg_trgm, unaccent ... check what schema_public.sql needs); harmless stubs for cron.schedule / cron.unschedule / cron.job, net.http_post / net.http_get (pg_net), vault and storage objects that public functions reference), then schema_system.sql where it helps, then schema_public.sql, then triggers.sql. Use the snapshot at origin/supabase-live-snapshot (e5d5b0f7). List every load error in the README and explain each (expected: PG17-only GRANT MAINTAIN, duplicate triggers); there must be no error that leaves a public table, function, trigger or policy missing - prove it by counting tables, functions, triggers, policies and indexes in the loaded database against the CREATE statements of the snapshot.\n'
  + '3. Scripts (bash, executable, each prints usage with -h): newdb.sh <name> (drop + create database <name> from template live_tpl); psql.sh <db> [psql args] (stdin passthrough); apply.sh <db> <file>... (each file exactly like the deploy: ON_ERROR_STOP=1, --single-transaction, stops at the first failure, prints NOTICEs and the failing statement); deploy_sim.sh <db> (applies every file of ' + R + '/supabase/migrations matching 20261112*.sql in LC_ALL=C sort order through apply.sh, recording file names in public._git_migrations like the workflow does; with --again it re-applies them all a second time to prove idempotency); sig.sh <db> (stable dump of all public function signatures, triggers, policies, indexes, columns, constraints, cron jobs - for before/after diffs); defn.sh <db> <function name> (prints pg_get_functiondef for every overload); rest_get.sh <table> <query string> (read-only REST GET with the anon key read from motogo-web-php/config.php at run time, paginated, writes JSON to stdout); seed_json.py <db> <table> <json file> (upsert rows fetched by rest_get.sh into the test database with session_replication_role = replica, only columns that exist).\n'
  + '4. A fake clock helper is NOT required unless a later agent needs it; mention that ' + H + '/rides/sql/run_tests.sh expects one (t_shim, t_set, t_now) and rebuild those helpers as test-only SQL in ' + SB + '/pg/timeshim.sql following the description in understand_server.md, because the ride tests need them. Also rebuild minimal fixtures (users, admin in admin_users, one motorcycle) as ' + SB + '/pg/fixtures.sql following that description.\n'
  + '5. Smoke test: newdb.sh smoke; apply a trivial file twice; sig.sh works; rest_get.sh reads 3 rows of a public table such as faq_items or cms_variables (report which public tables you probed and whether anon can read them: cms_variables, faq_items, cms_pages, app_settings, document_templates, email_templates, motorcycles, branches, loyalty levels table - find its real name in the schema).\n'
  + 'Return a short report: what exists, how to use it (the README path), load error summary with the object counts, REST readability table, anything a later agent must know.', { label: 'harness', phase: 'Harness' })

const GROUP_SCHEMA = {
  type: 'object',
  properties: {
    group: { type: 'string' },
    files: { type: 'array', items: { type: 'object', properties: { draft: { type: 'string' }, final: { type: 'string' }, summary: { type: 'string' } }, required: ['draft', 'final', 'summary'] } },
    excluded: { type: 'array', items: { type: 'object', properties: { draft: { type: 'string' }, why: { type: 'string' } }, required: ['draft', 'why'] } },
    applied_twice_ok: { type: 'boolean' },
    live_regression_check: { type: 'string' },
    data_failure_modes: { type: 'string' },
    tests: { type: 'string' },
    code_contract: { type: 'string' },
    open_issues: { type: 'array', items: { type: 'string' } },
    for_owner: { type: 'array', items: { type: 'string' } },
    state_patch: { type: 'string' },
    test_script: { type: 'string' },
    seed_script: { type: 'string' },
  },
  required: ['group', 'files', 'excluded', 'applied_twice_ok', 'live_regression_check', 'data_failure_modes', 'tests', 'open_issues', 'state_patch'],
}

const GROUP_COMMON = '\n\nHARNESS (built by the previous agent, read ' + HARNESS_DOC + ' first):\n' + harness + '\n\nYOUR DELIVERABLES (all of them):\n'
  + 'A. Final migration files in ' + R + '/supabase/migrations/ named per FILE NAMING for your group, in the migration file form. Write them only after the checks below pass.\n'
  + 'B. LIVE REGRESSION CHECK, object by object: for every function / trigger function / view your drafts replace and every trigger / policy / index / constraint they re-create, take the live definition of today (defn.sh on a fresh database, or the snapshot file) and diff it against the draft. Every difference must be explained by the purpose of the draft. If live has changed since the draft was written (a hunk present in live but missing in the draft, or the draft reverts live lines), REBASE the draft: start from the live body and re-apply only the intended change. Record the evidence (object, lines of difference, verdict) in ' + SB + '/<group>/regression.md.\n'
  + 'C. DATA FAILURE MODES: for every statement that can fail or misbehave depending on live data or on the transaction (unique indexes, constraints, NOT NULL, casts, jsonb paths, backfills, big updates, locks, cron/pg_net objects, objects that may or may not exist live), make it safe: pre-clean or guard, and where a failure is tolerable catch it and RAISE NOTICE/WARNING instead of aborting; where it is not tolerable, say why it cannot happen. Never hide real programming errors.\n'
  + 'D. APPLY TWICE: newdb.sh sqlb_<group>; apply your final files in order with apply.sh; apply them all a second time; compare sig.sh output after run 1 and run 2 (identical) and against the pristine template (only intended differences). Then run your group tests.\n'
  + 'E. CODE CONTRACT: list every RPC, table, column, trigger side effect that the code on this branch expects from your SQL (grep supabase/functions, Motogo-app-main/motogo-app-flutter/lib, velin/src, motogo-web-php) and confirm name, argument names, types and return shape match after your files are applied; also confirm clients in the field keep working (app 4.1.3 = git commit 70a94933 for both trees, the current live edge functions = origin/main:supabase/functions, the kiosk in raspberry/motogo-box): no dropped or re-typed argument, no removed column they read or write.\n'
  + 'F. A STATE patch ' + SB + '/state/<group>.md: precise additions/changes for SUPABASE_BACKEND_STATE_1 (tables), _2 (key columns), _3 (RPC functions), _4 (triggers), _5 (RLS, realtime, edge, storage, secrets, cron, FK) and a changelog paragraph for _6, written in Czech in the style those files use (grep a few neighbouring entries first). Do NOT edit the STATE files yourself.\n'
  + 'G. ' + SB + '/<group>/test.sh <db> - reruns your tests on any database where the whole bundle has been applied (exit code 0 = pass); and, if you fetched live rows, ' + SB + '/<group>/seed.sh <db> that loads them into a given database (must be run before the bundle is applied).\n'
  + 'Return the structured result. open_issues = anything unresolved that must be fixed before merge; for_owner = decisions or facts the owner must know (short, plain).'

phase('Groups')
const groupDefs = [
  { key: 'a', label: 'payments', task: 'GROUP a = payments (card minimum rounding to 15 CZK, customer restore-and-pay, swap completion, gear rounding + modified mail, one credit note per refund, web confirmation late refund, guard of pricing columns). Drafts: ' + H + '/sql-paydec/20261016p1_card_rounding.sql, 20261016p2_customer_restore.sql, 20261016p3_swap_card_rounding.sql, 20261016p4_gear_rounding_modified_mail.sql, 20261105a_uq_invoices_credit_note_refund.sql, 20261107a_web_booking_confirmation_late_refund.sql, 20261107b_guard_customer_booking_pricing.sql (identical copies exist in ' + S + '/paydec/sql; ' + H + '/paydec/sql/20261016p1 is an OLDER p1 - ignore it). Background: ' + H + '/sql-paydec/DESIGN.md (compare with ' + H + '/paydec/DESIGN.md and use the newer), fix reports ' + H + '/paydec/fix_i4_report.md, fix_i5r1_report.md, fix_i5r2_report.md, fix_i6r1_report.md. The code these serve is on this branch: supabase/functions (process-payment, webhook-receiver, process-refund, send-cancellation-email, send-booking-email and friends), the app (lib/features/payment, lib/features/reservations), the website (motogo-web-php/js pages-potvrzeni.js, guard.js, gear-rental-done.js ...), Velin (velin/src/pages/booking). Owner decisions: p1-p4 must go live together and together with the edge functions; 20261107b (customers may not change pricing columns of a paid booking through their JWT) was approved on 2026-11-08; the storno percentage base stays as live (no SQL change for that); Velin "Potvrdit vraceni" now sends cancel_total to process-refund (edge only, no SQL). Old app 4.1.3 must keep working (per DESIGN it gets below_minimum for 1-15 CZK card payments - check the RPC signatures it calls are unchanged or only extended with defaulted arguments). Special attention: these drafts are from 2026-10-16 and replace large payment/booking functions that main changed later (gear-only bookings 20261022/23, unified refund 20261023e, storno hotfix) - the rebase in deliverable B is essential here; 20261105a creates a unique index on invoices that can collide with existing duplicates on live data (cannot be read through REST) - it must not be able to fail (dedupe guard or DO block that skips with a WARNING and tells why). Keep each of p1..p4 atomic (one file each) unless a part is truly independent. Final names 20261112a01_... to a07_... in dependency order.' },
  { key: 'b', label: 'rides', task: 'GROUP b = ride recording (manual pause, automatic pause/resume, multi-day trip as one record, merging rides into a trip and back, sane statistics; owner request 2026-10-22). Drafts: ' + H + '/rides/sql/01_rides_columns.sql, 02_rides_stats_core.sql, 03a_rides_append.sql, 03b_rides_finish.sql, 03c_rides_append_finish.sql, 04_rides_start_cron.sql, 05_rides_trip_group.sql, 06_rides_backfill.sql; tests test_rides.sql and run_tests.sh (adapt paths to the new rig; it expects timeshim + fixtures from the harness), stats_vectors.json, overview PREHLED_CS.md; spec ' + H + '/rides/SPEC.md, client contract ' + H + '/rides/LOGIC_API.md, ready-made STATE patch ' + H + '/rides/STATE_PATCH.md (re-check it against your final files and copy the corrected version to ' + SB + '/state/b.md). The drafts were last verified on the live snapshot of 2026-11-05; re-verify on today. The app code is in lib/features/routes (ride_*.dart, both trees) and Velin (velin/src/pages/Trasy*.jsx, velin/src/lib/rideTrack.js). App 4.1.3 in the field must keep recording rides (its RPC calls keep their signatures; new arguments only with defaults) - prove with a signature diff before/after and by reading the 4.1.3 client calls (git show 70a94933:Motogo-app-main/motogo-app-flutter/lib/features/routes/...). The old traffic simulator is lost - do not rebuild it; run test_rides.sql twice as run_tests.sh does (including the concurrency race if feasible) and compare stats_vectors.json. 06 is a backfill over user_rides: it must be safe on a table of unknown size (bounded work, no long exclusive lock, tolerant to odd rows). 04 touches cron: on live pg_cron exists; the file must not fail if a job with that name already exists or is missing. Final names 20261112b01_... to b08_... .' },
  { key: 'c', label: 'reviews+colours', task: 'GROUPS c and d (two small groups, one agent). GROUP c = reviews and messages: drafts ' + H + '/sql-reviews/20261015_velin_rating_handled.sql, 20261015b_booking_rating_guard.sql, 20261015c_messages_bump_thread.sql -> 20261112c01.. c03 (owner request: ride rating leads to a Google review, "Napis nam primo, co mame zlepsit" goes to Velin tab Hodnoceni). The files DRAFT_20261015_faq_review_google_only.sql, OPTIONAL_20261015_booking_rating_reviews.sql and OPTIONAL_20261015d_ride_completed_review_links.sql are NOT planned: include one only if code on this branch cannot work without the objects it defines (grep app, Velin, web, edge) - otherwise list it under excluded with the reason. ' + H + '/sql-qa/20261016a_qa_messages_insert_policy.sql is deliberately left out of the whole bundle; make sure c03 does not depend on it. GROUP d = loyalty rank colours: draft ' + H + '/appdesign-v22/sql/20261016_loyalty_colors_ramp.sql -> 20261112d01 (the ramp green -> blue -> metals -> fiery gold at level 20 belongs to the approved app design v2.2; 20261015_loyalty_colors_no_purple.sql in the same folder is superseded and never applied). Read the live rows of the loyalty levels table through REST if anon can read it, seed them, and make sure the guards of d01 match the live values of today (if live differs from what the draft expects, keep the live values the draft does not own and report). Check who reads these colours: the old app look, the v2 look (lib/core/v2/rank), Velin, web - nothing may break or become unreadable (contrast) with the new values. Use ' + SB + '/c for both groups (state patch files ' + SB + '/state/c.md and ' + SB + '/state/d.md; one test.sh).' },
  { key: 't', label: 'owner texts', task: 'GROUP t = owner texts (data only): drafts ' + H + '/sql-final/*.sql (32 files, overview PREHLED.md) -> 20261112t01_... to t32_... keeping their order (keep the descriptive part of each name). Owner rule (2026-10-11, verbatim): "Myti ani tankovani neni treba na obsluzne pobocce. Na samoobsluze neni potreba tankovat. To dulezite je pouze, aby motorka byla umyta a nesvitila rezerva."; 2026-10-12: fuel level is not handled at all, never promise a full tank at pickup, no fuel fee. Plus approved texts: app also in the App Store, home step 3, banner translations, branches, gate procedure, e-mail templates. These files are compare-and-set: they change a text only where the live value still equals the value verified on 2026-10-15 and skip with a NOTICE otherwise. The open questions at the end of PREHLED.md are NOT to be resolved (owner: no). Older variants in ' + H + '/sql/*.sql are superseded - confirm and ignore. Work: (1) with rest_get.sh fetch the live rows of today for every table/key the files touch (cms_variables, faq_items, app_settings pages_overlay, cms_pages, branches, e-mail templates ... whatever they touch and anon may read) into ' + SB + '/t/live/, seed them (seed.sh), apply all 32 files twice. (2) Report per file: how many texts were changed, how many skipped because live changed since 2026-10-15 (for each skipped key: is the live text already compliant with the rule, or an owner edit that must stay, or a mismatch that leaves the website inconsistent with the PHP texts on this branch in motogo-web-php/data/*-content-*.php and motogo-web-php/lang/*.php). Never widen a guard so that it overwrites an edit made after 2026-10-15. (3) Robustness: no file may abort on live data (missing row or key, NULL jsonb, different jsonb shape, text already changed) - such cases become NOTICE + skip; a second run changes nothing. (4) Tables anon cannot read (probably email_templates, maybe app_settings): say so, review the guards by reading, and run the files on empty/synthetic rows to prove they do not raise. Put a per-file table into ' + SB + '/t/report.md. for_owner: the list of texts that will NOT change because someone edited them, in plain words.' },
  { key: 'u', label: 'QA texts', task: 'GROUP u = QA text and translation fixes (data only): drafts in ' + H + '/sql-qa/: 20261016b_qa_faq_review_google_only.sql, c_qa_translation_fixes, d_qa_texts_branches, e_qa_vop_stale_translations, f_qa_vop_footer_address, ga_qa_contract_stale_translations, h_qa_uk_texts, i_qa_faq_uk_1, j_qa_faq_uk_2, k_qa_moto_translations, l_qa_nl_wrong_language, m_qa_blog_top10_nl, w1_web_editrez_h1_terms, w2_web_blog_slug_p -> 20261112u01_... to u14_... . EXCLUDED on purpose: 20261016a_qa_messages_insert_policy.sql (left out of the bundle) and 20261016g_qa_binding_docs_washing.sql (changes binding documents - VOP art. 5 l) and the rental contract; the owner did not consent). Files e, f and ga touch document_templates (VOP and rental contract): they may only refresh stale machine translations and the footer address; if any of them changes the Czech source text or the legal meaning of a binding document, exclude that file (or that part) and report it under for_owner. Same procedure as for owner texts: fetch the live rows of today through REST into ' + SB + '/u/live/, seed, apply twice, per-file table of changed / skipped keys in ' + SB + '/u/report.md, robustness against live data, never overwrite a newer edit. Order matters: these run AFTER the owner texts (group t, drafts ' + H + '/sql-final/*.sql, being finalised in parallel by another agent as 20261112t*.sql) - in your database apply the t drafts first (as they are in the handoff folder), then your files, and check every key touched by both groups: the later guard must accept the result of the earlier file. Also check overlap with migrations already live (for example supabase/migrations/20261023f_faq_gear_rental.sql and other FAQ/CMS migrations after 2026-10-16).' },
]
const groups = (await parallel(groupDefs.map(g => () => agent(CTX + '\n\nTASK ' + g.task + GROUP_COMMON, { label: 'group:' + g.label, phase: 'Groups', schema: GROUP_SCHEMA, model: 'opus' })))).filter(Boolean)
log('groups done: ' + groups.map(g => g.group + ' ' + g.files.length + ' files, twice_ok=' + g.applied_twice_ok + ', open=' + g.open_issues.length).join(' | '))
const groupsText = JSON.stringify(groups, null, 1)

const REH_SCHEMA = { type: 'object', properties: { ok: { type: 'boolean' }, order: { type: 'array', items: { type: 'string' } }, failures: { type: 'array', items: { type: 'string' } }, tests: { type: 'string' }, delta_path: { type: 'string' }, notes: { type: 'string' } }, required: ['ok', 'order', 'failures', 'tests', 'delta_path'] }
const rehearse = (round) => agent(CTX + '\n\nHARNESS: read ' + HARNESS_DOC + '.\n\nGROUP RESULTS:\n' + groupsText + '\n\nTASK rehearsal (round ' + round + '). Rehearse the deploy of the WHOLE bundle exactly as it will happen on merge. (1) newdb.sh sqlb_reh' + round + '; run every group seed script that exists (' + SB + '/<group>/seed.sh sqlb_reh' + round + ') so the text migrations meet realistic rows; (2) deploy_sim.sh sqlb_reh' + round + ' (every supabase/migrations/20261112*.sql in LC_ALL=C order, each file in a single transaction with ON_ERROR_STOP); check the printed order is a..u with the sequence numbers and that no file name collides or sorts before 20261023f_; (3) save sig.sh output, then deploy_sim.sh --again and compare (must be identical; no error; data unchanged - compare row checksums of the seeded text tables before/after the second run); (4) run every ' + SB + '/<group>/test.sh on that database; (5) repeat steps 1-2 on a second fresh database WITHOUT any seed (empty tables) to prove no file depends on rows existing; (6) write ' + SB + '/rehearsal/schema_delta.md: every object added or changed versus the pristine live template (tables, columns, indexes, constraints, functions with full signatures, triggers, policies, grants, cron jobs), grouped by migration file - this is the input for the STATE documentation; (7) mechanical lint of every new file: no BEGIN/COMMIT/ROLLBACK statements, no CONCURRENTLY, header comment present, no leftover draft wording, file size (flag files above ~20 KB with the reason they are atomic), every CREATE FUNCTION is CREATE OR REPLACE, every SECURITY DEFINER function sets search_path. Do not fix migration files yourself in this task - report failures precisely (file, statement, error, suspected cause). ok = everything passed.', { label: 'rehearse:r' + round, phase: round === 1 ? 'Rehearse' : 'Fix', schema: REH_SCHEMA, model: 'opus' })

phase('Rehearse')
let reh = await rehearse(1)
log('rehearsal 1: ok=' + (reh && reh.ok) + ' failures=' + (reh ? reh.failures.length : '?'))

const ISSUES_SCHEMA = { type: 'object', properties: { issues: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor'] }, file: { type: 'string' }, title: { type: 'string' }, detail: { type: 'string' }, evidence: { type: 'string' }, fix: { type: 'string' } }, required: ['id', 'severity', 'file', 'title', 'detail', 'evidence', 'fix'] } }, verified_ok: { type: 'string' } }, required: ['issues', 'verified_ok'] }
const VER_COMMON = '\n\nHARNESS: read ' + HARNESS_DOC + ' (make your own database with newdb.sh sqlb_ver_<lens> and deploy_sim.sh it; never touch other databases).\n\nGROUP RESULTS:\n' + groupsText + '\n\nREHEARSAL RESULT:\n' + JSON.stringify(reh, null, 1) + '\n\nYou are an independent, adversarial reviewer of the final bundle supabase/migrations/20261112*.sql. Do not trust the group reports - check for yourself. Do not edit migration files. Report only real problems with evidence (the exact file, object, lines, a reproduction on the test database where possible). severity: blocker = can fail the deploy, lose or corrupt data, take money wrongly, or break a client in the field; major = wrong behaviour in a realistic case or an undone live change; minor = everything else. verified_ok = what you checked and found correct (specific). '
phase('Verify')
const lenses = [
  { key: 'regression', task: 'LENS live regression. For EVERY function, trigger function, view, trigger, policy, index and constraint that the bundle creates or replaces, diff the live definition of today (pristine template) against the definition after the bundle. List each object with the changed lines and decide whether every changed line is explained by the purpose of its migration (header + design docs in ' + H + '). Hunt specifically for live behaviour that the bundle silently removes or reverts: gear-only bookings (booking_kind = gear, moto_id NULL), unified refunds (20261023e_*), storno hotfix, kiosk release gates (pickup 12:00, automatic return completion), door codes, loyalty/promo, SOS. Also compare with the newest migration in supabase/migrations that touched the same object (git log / grep) to be sure the bundle started from it.' },
  { key: 'deploy', task: 'LENS deploy failure and data safety. For every statement decide whether it can fail, block or damage on the REAL live database, which has data the test rig lacks: unique indexes over existing duplicates, constraints over existing rows, NOT NULL, casts, jsonb paths on odd rows, UPDATE/DELETE without tight WHERE, backfills on big tables (user_rides tracks, bookings, invoices, messages), table rewrites and long ACCESS EXCLUSIVE locks while customers use the system, objects that exist live under another owner, pg_cron and pg_net differences from the stubs, statements illegal inside a single transaction, behaviour when a file is re-run after a partial earlier failure, and the second run. Try to break idempotency and the guards on the test database with hostile seed rows (duplicates, NULLs, half-migrated state, texts changed by the owner). For the text groups t and u: prove that a text edited after 2026-10-15 can never be overwritten.' },
  { key: 'contract', task: 'LENS contract and security. (1) Code versus SQL: for every rpc(...) call, table and column used by the code of this branch in supabase/functions, both app trees (lib/), velin/src and motogo-web-php, confirm it exists after the bundle with matching argument names, types, defaults and return shape; list anything the code needs that neither live nor the bundle provides, and anything the bundle adds that no code uses. (2) Clients in the field during and after the deploy window: app 4.1.3 (commit 70a94933, both trees), the live edge functions (origin/main:supabase/functions) running for some minutes against the new schema, the new edge functions running for some minutes against the old schema, the kiosk (raspberry/motogo-box) - nothing may break; name every RPC whose signature or behaviour changes for an old caller. (3) Security: every new or changed function - SECURITY DEFINER with search_path, who may EXECUTE (anon / authenticated / service_role) versus who should, RLS policies added or changed (can a customer read or change another customer rows, prices, payment state, loyalty, ride data?), triggers that trust client-supplied columns, the pricing guard (20261107b) - try to defeat it on the test database with a customer JWT (set role authenticated + request.jwt.claims). (4) supabase/config.toml: every edge function directory on this branch has a verify_jwt entry.' },
]
const ver1 = (await parallel(lenses.map(l => () => agent(CTX + VER_COMMON + '\n\nTASK ' + l.task, { label: 'verify:' + l.key, phase: 'Verify', schema: ISSUES_SCHEMA })))).filter(Boolean)
let issues = ver1.flatMap(v => v.issues)
const rehFails = reh && !reh.ok ? reh.failures : []
log('verify 1: ' + issues.length + ' issues (' + issues.filter(i => i.severity === 'blocker').length + ' blockers, ' + issues.filter(i => i.severity === 'major').length + ' major), rehearsal failures ' + rehFails.length)

phase('Fix')
const FIX_SCHEMA = { type: 'object', properties: { fixed: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, what: { type: 'string' } }, required: ['id', 'what'] } }, rejected: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, why: { type: 'string' } }, required: ['id', 'why'] } }, files_changed: { type: 'array', items: { type: 'string' } }, for_owner: { type: 'array', items: { type: 'string' } }, notes: { type: 'string' } }, required: ['fixed', 'rejected', 'files_changed'] }
const fixes = []
let round = 1
let openIssues = issues.filter(i => i.severity !== 'minor')
let minorIssues = issues.filter(i => i.severity === 'minor')
while ((openIssues.length || rehFails.length && round === 1) && round <= 3) {
  const fx = await agent(CTX + '\n\nHARNESS: read ' + HARNESS_DOC + '.\n\nGROUP RESULTS:\n' + groupsText + '\n\nTASK fix (round ' + round + '). Fix the following problems in the new migration files supabase/migrations/20261112*.sql (only those files; keep the file names; keep the migration file form; keep each change minimal and rebased on the live body). First reproduce each problem on your own database (newdb.sh sqlb_fix' + round + '), then fix, then prove the fix (apply twice, group tests). If a reported problem is not real, reject it with evidence. If a problem can only be solved in app/Velin/web/edge code, do NOT change that code - describe exactly what must change (file, function) under notes. Also fix the minor issues when the fix is trivial and safe. Update the affected ' + SB + '/state/<group>.md patch when an object changes. REHEARSAL FAILURES:\n' + JSON.stringify(round === 1 ? rehFails : (reh ? reh.failures : []), null, 1) + '\n\nISSUES:\n' + JSON.stringify(openIssues, null, 1) + '\n\nMINOR:\n' + JSON.stringify(round === 1 ? minorIssues : [], null, 1), { label: 'fix:r' + round, phase: 'Fix', schema: FIX_SCHEMA, model: 'opus' })
  fixes.push(fx)
  reh = await rehearse(round + 1)
  const re = await agent(CTX + VER_COMMON.replace(JSON.stringify(reh, null, 1), '') + '\n\nLATEST REHEARSAL:\n' + JSON.stringify(reh, null, 1) + '\n\nTASK re-verify (round ' + round + '). These problems were reported and a fix agent answered as follows. For each problem check on the test database whether it is really gone (or was rightly rejected), and look for new problems introduced by the changed files (run the three lenses - live regression, deploy/data safety, contract/security - but only over the files the fix changed and the objects it touched). Return only problems that are still open or new, same format.\n\nPROBLEMS:\n' + JSON.stringify(openIssues, null, 1) + '\n\nFIX ANSWER:\n' + JSON.stringify(fx, null, 1), { label: 'reverify:r' + round, phase: 'Fix', schema: ISSUES_SCHEMA, model: 'opus' })
  openIssues = re ? re.issues.filter(i => i.severity !== 'minor') : []
  if (reh && !reh.ok) openIssues = openIssues.concat(reh.failures.map((f, i) => ({ id: 'reh' + round + '-' + i, severity: 'blocker', file: '', title: 'rehearsal failure', detail: f, evidence: f, fix: '' })))
  log('fix round ' + round + ': still open ' + openIssues.length + ', rehearsal ok=' + (reh && reh.ok))
  round++
}

phase('State')
const STATE_IN = '\n\nINPUTS: the final migration files supabase/migrations/20261112*.sql; the group STATE patches ' + SB + '/state/*.md; ' + SB + '/rehearsal/schema_delta.md (objects added/changed, from the last rehearsal); the group results below; for edge functions: git -C ' + R + ' diff origin/main HEAD --stat -- supabase/functions and the design/fix reports in ' + H + '/paydec/ and ' + H + '/sql-paydec/DESIGN.md.\n\nGROUP RESULTS:\n' + groupsText + '\n\nFIXES:\n' + JSON.stringify(fixes, null, 1)
  + '\n\nSTATE FILE RULES: ' + R + '/SUPABASE_BACKEND_STATE_1..6.md document the LIVE backend after this PR is merged. They are very large: never rewrite or reformat them, only insert new entries / amend the entries of changed objects, in the style and language (Czech) of the neighbouring entries, with the date 2026-11-12 and the migration file name. Find the right place with grep (object name) and edit surgically (Edit tool or a small script that inserts at an exact anchor line; verify with git diff --stat that only your lines changed). No git write commands.'
const stateTasks = [
  { key: 'st12', task: 'STATE_1 (tables) and STATE_2 (key columns): every new table, column, index, constraint, default and changed column of the bundle.' },
  { key: 'st3', task: 'STATE_3 (RPC functions): every new or changed function of the bundle - signature, who may call it, what changed and why, back-compat notes for app 4.1.3.' },
  { key: 'st45', task: 'STATE_4 (triggers) and STATE_5 (RLS, Realtime, Edge functions, Storage, Secrets, Cron, FK): triggers and trigger functions, policies, grants, cron jobs, foreign keys of the bundle; AND the edge-function changes of this branch versus origin/main (supabase/functions: new and changed functions and shared modules, new request parameters such as process-refund cancel_total, new behaviours of process-payment, webhook-receiver, process-refund, send-cancellation-email, send-booking-email; supabase/config.toml entries) in the Edge section.' },
  { key: 'st6', task: 'STATE_6 (changelog): one entry dated 2026-11-12 placed where the newest entries go (check the order used at the top of the file and around the 2026-10-29 / 2026-11 entries), summarising the whole PR for a future session: SQL bundle by group with file names, edge-function changes, Velin changes that depend on them (refund confirmation = total storno amount capped at what the customer paid, ride map estimates, route editor), website and app contract notes (app 4.2.0 both platforms, kill-switch feature_flags.app_v2_ui), what was deliberately NOT included (sql-qa a and g, optional review files) and the deploy order facts (functional migrations a-d before text migrations t-u).' },
]
const stateRes = (await parallel(stateTasks.map(s => () => agent(CTX + STATE_IN + '\n\nTASK state:' + s.key + '. Update ' + s.task + ' Return a short list of what you inserted where (file, anchor, object).', { label: 'state:' + s.key, phase: 'State', model: 'opus' })))).filter(Boolean)
const stateCheck = await agent(CTX + STATE_IN + '\n\nSTATE AGENT REPORTS:\n' + stateRes.join('\n\n----\n\n') + '\n\nTASK state check. Verify the STATE documentation against the final bundle: build a checklist of every object in ' + SB + '/rehearsal/schema_delta.md and every edge-function change, and confirm each is documented in the right STATE file with the right name, signature and migration file name; confirm nothing documents an object that the bundle does not create; confirm git diff of the six files contains only insertions/amendments for this PR (no accidental deletions or reformatting - check git diff --stat and scan for removed lines). Fix omissions and errors directly in the STATE files (surgically). Return: what you checked, what you corrected, anything still doubtful.', { label: 'state:check', phase: 'State', model: 'opus' })

return { harness, groups, rehearsal: reh, verify1: ver1, fixes, open_after_fix: openIssues, state: stateRes, stateCheck }
